updateUser(
            @Parameter(description = "用户ID") @PathVariable Long userId,
            @RequestBody @Valid UserForm userForm
    )

deleteUsers(
            @Parameter(description = "用户ID，多个以英文逗号(,)分割") @PathVariable String ids
    )

updateUserStatus(
            @Parameter(description = "用户ID") @PathVariable Long userId,
            @Parameter(description = "用户状态(1:启用;0:禁用)") @RequestParam Integer status
    )

resetUserPassword(
            @Parameter(description = "用户ID") @PathVariable Long userId,
            @RequestParam String password
    )

sendMobileCode(
            @Parameter(description = "手机号码", required = true) @RequestParam String mobile
    )

sendEmailCode(
            @Parameter(description = "邮箱地址", required = true) @RequestParam String email
    )

downloadZip(HttpServletResponse response, @PathVariable String tableName,
                            @RequestParam(value = "pageType", required = false, defaultValue = "classic") String pageType,
                            @RequestParam(value = "type", required = false, defaultValue = "ts") String type)
